using MovieInfoBackend.DataModels;
using Xunit.Abstractions;

public class TmdbTvSeasonDataModelTests
{
    private string tmdbHttpClientTvSeasonResponse;

    public TmdbTvSeasonDataModelTests(ITestOutputHelper output)
    {
        // Arrange

        string testTvSeasonDataFilename = "TmdbHttpClientTvSeasonResponse.json";

        using (StreamReader sr = File.OpenText($"../../../TestData/{testTvSeasonDataFilename}"))
        {
            tmdbHttpClientTvSeasonResponse = sr.ReadToEnd();
        }
        if (String.IsNullOrWhiteSpace(tmdbHttpClientTvSeasonResponse))
        {
            throw new ArgumentException($"{testTvSeasonDataFilename} is not valid test data.");
        }
    }

    [Fact]
    public void GetModelFromResponse_ValidResponse_ReturnsValidModels()
    {
        // Act
        
        TmdbTvSeasonResponseDataModel? tvSeasonResponse = TmdbHttpClient.GetTvSeasonModelFromResponse(tmdbHttpClientTvSeasonResponse);
        
        // Assert

        Assert.NotNull(tvSeasonResponse);
        Assert.False(String.IsNullOrWhiteSpace(tvSeasonResponse.Id1), "TV season Id1 must not be empty");
        // Episodes
        Assert.NotEmpty(tvSeasonResponse.Episodes);
        TmdbTvSeasonEpisodeDataModel firstEpisode = tvSeasonResponse.Episodes[0];
        Assert.True(firstEpisode.EpisodeNumber > 0, "TV season episode EpisodeNumber must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstEpisode.EpisodeType), "TV season episode EpisodeType must not be empty");
        Assert.True(firstEpisode.Id > 0, "TV season episode Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstEpisode.Name), "TV season episode Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstEpisode.Overview), "TV season episode Overview must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstEpisode.ProductionCode), "TV season episode ProductionCode must not be empty");
        Assert.True(firstEpisode.Runtime > 0, "TV season episode Runtime must be a positive number");
        Assert.True(firstEpisode.SeasonNumber > 0, "TV season episode SeasonNumber must be a positive number");
        Assert.True(firstEpisode.ShowId > 0, "TV season episode ShowId must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstEpisode.StillPath), "TV season episode StillPath must not be empty");
        Assert.True(firstEpisode.VoteAverage >= 0.0, "TV season episode VoteAverage must not be a negative decimal number");
        Assert.True(firstEpisode.VoteCount >= 0, "TV season episode VoteCount must not be a negative number");
        Assert.NotEmpty(firstEpisode.Crew);
        // Episode crew
        TmdbTvSeasonEpisodeCrewDataModel firstCrew = firstEpisode.Crew[0];
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.Department), "TV season episode crew Department must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.Job), "TV season episode crew Job must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.CreditId), "TV season episode crew CreditId must not be empty");
        Assert.True(firstCrew.Gender >= 0, "TV season episode crew Gender must not be a negative number");
        Assert.True(firstCrew.Id > 0, "TV season episode crew Id must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.KnownForDepartment), "TV season episode crew KnownForDepartment must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.Name), "TV season episode crew Name must not be empty");
        Assert.False(String.IsNullOrWhiteSpace(firstCrew.OriginalName), "TV season episode crew OriginalName must not be empty");
        Assert.True(firstCrew.Popularity >= 0.0, "TV season episode crew Popularity must not be a negative decimal number");
        // Episode guest star
        if (firstEpisode.GuestStars.Length > 0)
        {
            TmdbTvSeasonEpisodeGuestStarDataModel firstGuestStar = firstEpisode.GuestStars[0];
            Assert.False(String.IsNullOrWhiteSpace(firstGuestStar.Character), "TV season episode guest star Character must not be empty");
            Assert.False(String.IsNullOrWhiteSpace(firstGuestStar.CreditId), "TV season episode guest star CreditId must not be empty");
            Assert.True(firstGuestStar.Order >= 0, "TV season episode guest star Order must not be a negative number");
            Assert.True(firstGuestStar.Gender >= 0, "TV season episode guest star Gender must not be a negative number");
            Assert.True(firstGuestStar.Id > 0, "TV season episode guest star Id must be a positive number");
            Assert.False(String.IsNullOrWhiteSpace(firstGuestStar.KnownForDepartment), "TV season episode guest star KnownForDepartment must not be empty");
            Assert.False(String.IsNullOrWhiteSpace(firstGuestStar.Name), "TV season episode guest star Name must not be empty");
            Assert.False(String.IsNullOrWhiteSpace(firstGuestStar.OriginalName), "TV season episode guest star OriginalName must not be empty");
            Assert.True(firstGuestStar.Popularity >= 0.0, "TV season episode guest star Popularity must not be a negative decimal number");
        }
        // End episode
        Assert.False(String.IsNullOrWhiteSpace(tvSeasonResponse.Name), "TV season Name must not be empty");
        // Season network
        if (tvSeasonResponse.Networks.Length > 0)
        {
            TmdbNetworkDataModel firstNetwork = tvSeasonResponse.Networks[0];
            Assert.True(firstNetwork.Id > 0, "TV season network Id must be a positive number");
            Assert.False(String.IsNullOrWhiteSpace(firstNetwork.Name), "TV season network Name must not be empty");
            Assert.False(String.IsNullOrWhiteSpace(firstNetwork.OriginCountry), "TV season network OriginCountry must not be empty");
        }
        Assert.False(String.IsNullOrWhiteSpace(tvSeasonResponse.Overview), "TV season Overview must not be empty");
        Assert.True(tvSeasonResponse.Id2 > 0, "TV season Id2 must be a positive number");
        Assert.False(String.IsNullOrWhiteSpace(tvSeasonResponse.PosterPath), "TV season PosterPath must not be empty");
        Assert.True(tvSeasonResponse.SeasonNumber > 0, "TV season SeasonNumber must be a positive number");
        Assert.True(tvSeasonResponse.VoteAverage >= 0.0, "TV season VoteAverage must not be a negative decimal number");
    }

